INSERT INTO `lowongan` (`id`, `kode_lowongan`, `posisi`, `perusahaan`, `bidang`, `tipe`, `lokasi`, `gaji`, `deskripsi`, `status`, `created_at`) VALUES
(1, 'LKR-001', 'Teknisi Jaringan & Fiber Optic', 'Nusantara Soft Techno', 'Teknik Komputer', 'Full-time', 'Semarang (Hybrid)', 'UMK Sesuai Daerah', 'Nusantara Soft Techno membuka lowongan untuk menangani infrastruktur IT.\n\nTanggung Jawab & Kualifikasi:\n• Instalasi, monitoring, dan troubleshooting jaringan komputer (LAN/WAN, Fiber Optic, Wi-Fi).\n• Pemeliharaan server Linux/Windows dan backup data rutin.\n• Menguasai konfigurasi routing Mikrotik, Cisco, atau perangkat sejenis.\n• Siap bertindak cepat saat terjadi kendala jaringan (downtime).', 'Dibuka', '2026-11-17 10:45:31'),
(2, 'LKR-002', 'Staff IT Support & Helpdesk', 'PT Sentosa Distribusi Pangan', 'Teknik Komputer', 'Full-time', 'Purbalingga', 'UMK Sesuai Daerah', 'PT Sentosa Distribusi Pangan membuka lowongan untuk menangani infrastruktur IT.\n\nTanggung Jawab & Kualifikasi:\n• Instalasi, monitoring, dan troubleshooting jaringan komputer (LAN/WAN, Fiber Optic, Wi-Fi).\n• Pemeliharaan server Linux/Windows dan backup data rutin.\n• Menguasai konfigurasi routing Mikrotik, Cisco, atau perangkat sejenis.\n• Siap bertindak cepat saat terjadi kendala jaringan (downtime).', 'Dibuka', '2026-11-17 10:45:31'),
(3, 'LKR-003', 'Motion Graphic Animator', 'CV Prima Artha Mandiri', 'Desain & Media', 'Part-time', 'Remote / WFH', 'Komisi + Rp 1.500.000', 'CV Prima Artha Mandiri mencari insan kreatif untuk memperkuat tim produksi konten visual.\n\nTanggung Jawab & Kualifikasi:\n• Memproduksi aset visual untuk media sosial, promosi digital, dan materi branding.\n• Menguasai Adobe Creative Suite (Photoshop, Illustrator, Premiere, After Effects).\n• Memiliki selera visual yang kuat, pemahaman komposisi warna dan tipografi.\n• Wajib menyertakan tautan portofolio aktif pada berkas lamaran.', 'Dibuka', '2026-11-17 10:45:31'),
(4, 'LKR-004', 'Peserta Magang Pengelasan & Fabrikasi', 'CV Makmur Sejahtera Abadi', 'Otomotif & Manufaktur', 'Magang / PKL', 'Bandung', 'Sertifikat & Uang Saku Transport', 'Praktik Kerja Industri di bengkel dan fasilitas produksi CV Makmur Sejahtera Abadi.\n\nKompetensi & Syarat:\n• Siswa SMK jurusan TKRO, TBSM, Teknik Pemesinan, atau Teknik Pengelasan.\n• Memahami dasar servis berkala, tune-up, dan perkakas tangan (hand tools).\n• Mematuhi standar K3 (Keselamatan dan Kesehatan Kerja) serta disiplin waktu.', 'Ditutup', '2026-11-17 10:45:31'),
(5, 'LKR-005', 'Digital Marketing Specialist', 'PT Solusi Cipta Digital', 'Pemasaran', 'Full-time', 'Remote / WFH', 'Rp 6.000.000 - Rp 8.500.000', 'PT Solusi Cipta Digital membuka kesempatan karir di divisi pemasaran dan penjualan.\n\nTanggung Jawab & Kualifikasi:\n• Merancang strategi akuisisi pelanggan, digital ads, dan manajemen kampanye produk.\n• Menganalisis metrik performa (conversion rate, ROAS, engagement rate).\n• Memiliki kemampuan negosiasi, presentasi, dan orientasi pada target target penjualan.\n• Terbiasa membangun relasi bisnis yang positif.', 'Dibuka', '2026-11-17 10:45:31'),
(6, 'LKR-006', 'Peserta Magang Desain Grafis (DKV)', 'PT Prima Auto Perkasa', 'Desain & Media', 'Magang / PKL', 'Cirebon', 'Sertifikat & Uang Saku Transport', 'Magang industri kreatif di PT Prima Auto Perkasa untuk siswa SMK DKV/Animasi/Multimedia.\n\nSyarat & Keterampilan:\n• Menguasai dasar Adobe Illustrator, Photoshop, atau Canva/Premiere Pro.\n• Melampirkan portofolio karya desain atau video yang pernah dibuat.\n• Kreatif, mengikuti tren visual terkini, dan berinisiatif tinggi.', 'Ditutup', '2026-11-17 10:45:31'),
(7, 'LKR-007', 'Peserta Magang Digital Marketing', 'PT Graha Finansial Terpadu', 'Pemasaran', 'Magang / PKL', 'Jakarta Barat', 'Sertifikat & Uang Saku Transport', 'Program magang pemasaran digital di PT Graha Finansial Terpadu untuk siswa jurusan BDP/Bisnis Daring.\n\nTugas & Persyaratan:\n• Membantu riset tren media sosial, pembuatan caption, dan interaksi dengan audiens.\n• Memahami dasar platform marketplace (Shopee, Tokopedia, TikTok Shop).\n• Aktif di media sosial, komunikatif, dan senang mencoba hal baru.', 'Dibuka', '2026-11-17 10:45:31'),
(8, 'LKR-008', 'Service Advisor Bengkel Resmi', 'CV Karya Baja Mandiri', 'Otomotif & Manufaktur', 'Full-time', 'Surakarta', 'Rp 4.000.000 - Rp 5.500.000', 'CV Karya Baja Mandiri mencari tenaga terampil di bidang otomotif dan manufaktur.\n\nTanggung Jawab & Kualifikasi:\n• Melakukan perawatan, diagnosa kerusakan mesin, dan perbaikan komponen presisi.\n• Memahami pembacaan manual book teknis dan penggunaan alat ukur (vernier caliper, mikrometer).\n• Disiplin, memiliki ketahanan fisik yang baik, dan mampu bekerja sesuai target pabrik.\n• Sertifikasi keahlian teknis menjadi nilai tambah.', 'Dibuka', '2026-11-17 10:45:31'),
(9, 'LKR-009', 'Staff Pengadaan Barang (Procurement)', 'Bengkel Resmi Jaya Motor', 'Administrasi', 'Full-time', 'Surakarta', 'Rp 4.500.000 - Rp 6.000.000', 'Bengkel Resmi Jaya Motor mencari staf administrasi yang handal dan terorganisir.\n\nTanggung Jawab & Kualifikasi:\n• Mengelola administrasi harian, rekap data inventaris, dan korespondensi bisnis.\n• Menguasai Microsoft Excel tingkat menengah (VLOOKUP, Pivot Table, IF).\n• Komunikasi interpersonal yang baik dan mampu bekerja sesuai deadline.\n• Pendidikan minimal SMK/D3/S1 jurusan relevan.', 'Ditutup', '2026-11-17 10:45:31'),
